SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(f),'relation',to_jsonb(pg_identify_object('pg_class'::regclass,f.ftrelid,0)),'server',s.srvname,'server_oid',s.oid) ORDER BY f.ftrelid),'[]'::jsonb) AS payload FROM pg_foreign_table f JOIN pg_foreign_server s ON s.oid=f.ftserver WHERE f.ftrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)) AS capture